const POP_MS = 280;   // must match the transform/radius duration above

function popOrigin(placement = 'bottom') {
  if (placement.startsWith('bottom')) return placement.endsWith('-end') ? 'top right'    : 'top left';
  if (placement.startsWith('top'))    return placement.endsWith('-end') ? 'bottom right' : 'bottom left';
  if (placement.startsWith('left'))   return placement.endsWith('-end') ? 'bottom right' : 'top right';
  if (placement.startsWith('right'))  return placement.endsWith('-end') ? 'bottom left'  : 'top left';
  return 'top left';
}

function openPopover(el, opt = {}) {
  el.style.transformOrigin = popOrigin(opt.placement);
  el.style.display = 'block';              // must paint before it can transition
  el.classList.remove('is-open');
  // double rAF: give the browser a painted "dot" frame to animate FROM
  requestAnimationFrame(() => requestAnimationFrame(() => el.classList.add('is-open')));
}

function closePopover(el) {
  el.classList.remove('is-open');                          // reverse the morph
  setTimeout(() => { el.style.display = 'none'; }, POP_MS); // hide after it finishes
}

