// CSS (.pop / .pop.is-open) lives in your global stylesheet.
import { useEffect, useRef, useState } from "react";

const POP_MS = 280;

function popOrigin(placement = "bottom") {
  if (placement.startsWith("bottom")) return placement.endsWith("-end") ? "top right"    : "top left";
  if (placement.startsWith("top"))    return placement.endsWith("-end") ? "bottom right" : "bottom left";
  if (placement.startsWith("left"))   return placement.endsWith("-end") ? "bottom right" : "top right";
  if (placement.startsWith("right"))  return placement.endsWith("-end") ? "bottom left"  : "top left";
  return "top left";
}

export default function Popover({ placement = "bottom-start" }) {
  const panel = useRef(null);
  const [open, setOpen] = useState(false);

  useEffect(() => {
    const el = panel.current;
    if (open) {
      el.style.transformOrigin = popOrigin(placement);
      el.style.display = "block";
      el.classList.remove("is-open");
      // double rAF: paint the "dot" frame before morphing open
      requestAnimationFrame(() =>
        requestAnimationFrame(() => el.classList.add("is-open"))
      );
    } else {
      el.classList.remove("is-open");
      const id = setTimeout(() => { el.style.display = "none"; }, POP_MS);
      return () => clearTimeout(id);
    }
  }, [open, placement]);

  return (
    <div className="pop-anchor">
      <button onClick={() => setOpen((o) => !o)}>Options</button>
      <div ref={panel} className="pop" style={{ display: "none" }}>
        menu items
      </div>
    </div>
  );
}

