import { useEffect, useRef, useState } from "react";

export default function StickyHeader({ threshold = 8 }) {
  const scroller = useRef(null);
  const [stuck, setStuck] = useState(false);

  useEffect(() => {
    const el = scroller.current;
    let ticking = false;
    const onScroll = () => {
      if (ticking) return;
      ticking = true;
      requestAnimationFrame(() => {
        setStuck(el.scrollTop > threshold);
        ticking = false;
      });
    };
    el.addEventListener("scroll", onScroll);
    return () => el.removeEventListener("scroll", onScroll);
  }, [threshold]);

  return (
    <div ref={scroller} style={{ height: 300, overflowY: "auto" }}>
      <header className={"sticky-head" + (stuck ? " is-stuck" : "")}>
        <div className="sh-title">Work orders</div>
        <div className="sh-sub">128 open across Tower A-C</div>
      </header>
      {/* long content that makes the area scroll */}
    </div>
  );
}

