function initTabs(root) {
  const bar = root.querySelector('.tabbar');
  const line = root.querySelector('.tab-underline');
  const btns = [].slice.call(root.querySelectorAll('.tab-btn'));
  const panels = [].slice.call(root.querySelectorAll('.tab-panel'));
  let cur = 0;
  const moveTo = (el) => { line.style.left = el.offsetLeft + 'px'; line.style.width = el.offsetWidth + 'px'; };
  function select(i) {
    cur = i;
    btns.forEach((b, j) => b.classList.toggle('is-active', j === i));
    panels.forEach((p, j) => p.classList.toggle('is-active', j === i));
    moveTo(btns[i]);
  }
  btns.forEach((b, i) => {
    b.addEventListener('click', () => select(i));
    b.addEventListener('mouseenter', () => moveTo(b));   // hover slides the underline
  });
  bar.addEventListener('mouseleave', () => moveTo(btns[cur])); // settle back on active
  addEventListener('resize', () => moveTo(btns[cur]));
  select(0);
}

