import { useLayoutEffect, useRef, useState } from "react";

const TABS = ["Details", "Activity", "Files"];

export default function Tabs() {
  const [i, setI] = useState(0);
  const [hover, setHover] = useState(null);   // hovered tab, or null
  const barRef = useRef(null);
  const [line, setLine] = useState({ left: 0, width: 0 });
  useLayoutEffect(() => {
    const idx = hover == null ? i : hover;
    const b = barRef.current.querySelectorAll(".tab-btn")[idx];
    setLine({ left: b.offsetLeft, width: b.offsetWidth });
  }, [i, hover]);
  return (
    <div>
      <div className="tabbar" ref={barRef} onMouseLeave={() => setHover(null)}>
        {TABS.map((t, j) => (
          <button key={t} className={"tab-btn" + (i === j ? " is-active" : "")}
                  onMouseEnter={() => setHover(j)} onClick={() => setI(j)}>{t}</button>
        ))}
        <span className="tab-underline" style={{ left: line.left, width: line.width }} />
      </div>
      <div className="tab-panel is-active" key={i}>{TABS[i]}</div>
    </div>
  );
}

