export default function BulkList() {
  const [sel, setSel] = useState(() => new Set());
  const toggle = (i) => setSel((s) => {
    const n = new Set(s);
    n.has(i) ? n.delete(i) : n.add(i);
    return n;
  });
  return (
    <div style={{ position: "relative" }}>
      <ul>
        {ROWS.map((r, i) => (
          <li key={i}>
            <input type="checkbox" checked={sel.has(i)} onChange={() => toggle(i)} /> {r}
          </li>
