/* ---------- JS ---------- */
function initSlideNav(nav, onSelect) {
  const sel = nav.querySelector('.snav__sel');
  const hov = nav.querySelector('.snav__hover');
  const items = [].slice.call(nav.querySelectorAll('.snav__item'));
  const place = (g, el) => { g.style.left = el.offsetLeft + 'px'; g.style.width = el.offsetWidth + 'px'; };
  const active = () => nav.querySelector('.snav__item.is-active') || items[0];
  items.forEach((it, i) => {
    it.addEventListener('mouseenter', () => {         // hover indicator slides with the cursor
      if (it.classList.contains('is-active')) { hov.style.opacity = 0; return; }
      place(hov, it); hov.style.opacity = 1;
    });
    it.addEventListener('click', () => {              // selected slides from current to clicked
      items.forEach((x) => x.classList.remove('is-active'));
      it.classList.add('is-active');
      place(sel, it); hov.style.opacity = 0;
      onSelect && onSelect(i, it);
    });
  });
  nav.addEventListener('mouseleave', () => { hov.style.opacity = 0; });
  place(sel, active());
  addEventListener('resize', () => place(sel, active()));
}

