import { useLayoutEffect, useRef, useState } from "react";

const ITEMS = ["List", "Kanban", "Calendar"];

export default function SlideNav() {
  const [active, setActive] = useState(0);
  const [hover, setHover] = useState(null);
  const navRef = useRef(null);
  const [sel, setSel] = useState({ left: 0, width: 0 });
  const [hov, setHov] = useState({ left: 0, width: 0, opacity: 0 });
  const boxOf = (i) => {
    const el = navRef.current.querySelectorAll(".snav__item")[i];
    return { left: el.offsetLeft, width: el.offsetWidth };
  };
  useLayoutEffect(() => { setSel(boxOf(active)); }, [active]);            // selected slides on click
  useLayoutEffect(() => {                                                // hover slides with the cursor
    if (hover == null || hover === active) { setHov((h) => ({ ...h, opacity: 0 })); return; }
    setHov({ ...boxOf(hover), opacity: 1 });
  }, [hover, active]);
  return (
    <div className="snav" ref={navRef} onMouseLeave={() => setHover(null)}>
      <span className="snav__sel" style={{ left: sel.left, width: sel.width }} />
      <span className="snav__hover" style={{ left: hov.left, width: hov.width, opacity: hov.opacity }} />
      {ITEMS.map((t, i) => (
        <button key={t} className={"snav__item" + (active === i ? " is-active" : "")}
                onMouseEnter={() => setHover(i)} onClick={() => setActive(i)}>{t}</button>
      ))}
    </div>
  );
}

