.reorder-item { display: flex; align-items: center; gap: var(--spacing-containerLarge);
  padding: var(--spacing-containerLarge) var(--spacing-containerXLarge);
  border: 1px solid var(--colors-borderNeutralBaseSubtle); border-radius: var(--border-large);
  background: var(--colors-backgroundContainer); cursor: grab; }
.reorder-item.dragging { opacity: .4; }
/* the FLIP transition is applied inline by the JS below */

/* ---------- JS — FLIP: First, Last, Invert, Play ---------- */
function initReorder(list) {
  let dragEl = null;
  const items = () => [].slice.call(list.querySelectorAll('[draggable]'));
  function flip(reorder) {
    const els = items();
    const first = els.map((el) => el.getBoundingClientRect());   // First
    reorder();                                                    // (DOM changes)
    els.forEach((el, i) => {
      if (el === dragEl) return;
      const last = el.getBoundingClientRect();                    // Last
      const dx = first[i].left - last.left, dy = first[i].top - last.top;
      if (!dx && !dy) return;
      el.style.transition = 'none';
      el.style.transform = 'translate(' + dx + 'px,' + dy + 'px)'; // Invert
      requestAnimationFrame(() => {
        el.style.transition = 'transform .3s cubic-bezier(.16, 1, .3, 1)';
        el.style.transform = '';                                   // Play
      });
    });
  }
  list.addEventListener('dragstart', (e) => { dragEl = e.target.closest('[draggable]'); setTimeout(() => dragEl.classList.add('dragging'), 0); });
  list.addEventListener('dragend', () => { if (dragEl) dragEl.classList.remove('dragging'); dragEl = null; });
  list.addEventListener('dragover', (e) => {
    e.preventDefault();
    if (!dragEl) return;
    const over = e.target.closest('[draggable]');
    if (!over || over === dragEl) return;
    const r = over.getBoundingClientRect();
    const ref = (e.clientY - r.top) > r.height / 2 ? over.nextElementSibling : over;
    if (ref === dragEl || dragEl.nextElementSibling === ref) return;
    flip(() => list.insertBefore(dragEl, ref));
  });
}

