// The built-in 'heatmap' series does NOT animate its entrance, so we draw the
// grid as a 'custom' series — which honours animationDelay for a staggered reveal.
const data = [ /* [xIndex, yIndex, value] triples, value 0-100 */ ];
const option = {
  grid: { left: 8, right: 8, top: 8, bottom: 24, containLabel: true },
  xAxis: { type: 'category', data: ['Mon','Tue','Wed','Thu','Fri','Sat'] },
  yAxis: { type: 'category', data: ['00', '06', '12', '18'] },
  series: [{
    type: 'custom',
    coordinateSystem: 'cartesian2d',
    data,
    renderItem: (params, api) => {
      const c = api.coord([api.value(0), api.value(1)]);   // cell center
      const s = api.size([1, 1]);                          // cell size
      const t = Math.max(0, Math.min(1, api.value(2) / 100));
      const mix = (a, b) => Math.round(a + (b - a) * t);   // light -> primary
      return {
        type: 'rect',
        shape: { x: c[0] - s[0] / 2 + 2, y: c[1] - s[1] / 2 + 2, width: s[0] - 4, height: s[1] - 4, r: 3 },
        style: { fill: 'rgb(' + mix(238, 21) + ',' + mix(244, 112) + ',' + mix(255, 239) + ')' }
      };
    },
    animationDuration: 500,
    animationEasing: 'cubicOut',
    animationDelay: (i) => i * 22     // diagonal ripple
  }]
};

