.pvt-cell { display: inline-block; opacity: 0; }
.pvt.play .pvt-cell { animation: pvtIn .4s cubic-bezier(.16, 1, .3, 1) both; animation-delay: calc(var(--i, 0) * .035s); }
@keyframes pvtIn { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) { .pvt.play .pvt-cell { animation: none; } .pvt-cell { opacity: 1; } }

/* ---------- JS — index every cell, then toggle .play ---------- */
function playPivot(table) {
  [].slice.call(table.querySelectorAll('.pvt-cell')).forEach((c, i) => c.style.setProperty('--i', i));
  table.classList.remove('play');
  void table.offsetWidth;              // reflow so it can replay
  table.classList.add('play');
}

