// CSS (.pvt-cell + pvtIn) lives in your global stylesheet.
import { useLayoutEffect, useRef } from "react";

const ROWS = [
  { name: "Tower A", vals: [128, 142, 270] },
  { name: "Tower B", vals: [96, 88, 184] }
];

export default function Pivot() {
  const ref = useRef(null);
  useLayoutEffect(() => {
    const cells = ref.current.querySelectorAll(".pvt-cell");
    cells.forEach((c, i) => c.style.setProperty("--i", i));
    ref.current.classList.add("play");
  }, []);
  return (
    <table ref={ref} className="pvt">
      <thead><tr><th>Building</th><th>Jan</th><th>Feb</th><th>Q1</th></tr></thead>
      <tbody>
        {ROWS.map((r, i) => (
          <tr key={i}>
            <td><span className="pvt-cell">{r.name}</span></td>
            {r.vals.map((v, j) => <td key={j}><span className="pvt-cell">{v}</span></td>)}
          </tr>
        ))}
      </tbody>
    </table>
  );
}
